// ПЛК-локации для elevator.lam (закрывает РИ4: модель написана под МК-адресацию 0x10000000…)
//
// Внешняя карта адресов (фича 0020) для цели st-at: держит ПЛК-локации
// ОТДЕЛЬНО от модели. Сама модель не правится — она корректна для целей
// c/c-hal; под ПЛК адреса переопределяются здесь (приоритет: inline <
// address < внешняя карта).
//
// Класс локации (%I / %Q) генератор берёт из направления порта, поэтому
// входы и выходы нумеруются независимо. Для bit-порта адрес — номер БАЙТА,
// а бит — позиция в нём: 8 портов на байт.
//

// ── Входы → %IX ──
sensors_1 = 0x0;
sensors_2 = 0x1;
sensors_3 = 0x2;
sensors_4 = 0x3;
sensors_5 = 0x4;
sensors_6 = 0x5;
sensors_7 = 0x6;
sensors_8 = 0x7;
sensors_9 = 0x8;
sensors_cab = 0x9;
btns_floor_1 = 0xA;
btns_floor_2 = 0xB;
btns_floor_3 = 0xC;
btns_floor_4 = 0xD;
btns_floor_5 = 0xE;
btns_floor_6 = 0xF;
btns_floor_7 = 0x10;
btns_floor_8 = 0x11;
btns_floor_9 = 0x12;
btns_cab_lo = 0x13;
btns_cab_hi = 0x14;

